    def numberOfPowerfulInt(self, start: int, finish: int, limit: int, s: str) -> int:
        def count(n):
            if n < 0:
                return 0
            if n < int(s):
                return 0

            n_str = str(n)
            s_len = len(s)
            n_len = len(n_str)

            # If n has fewer digits than s, impossible
            if n_len < s_len:
                return 0

            # If n has exactly s_len digits, check if it ends with s
            if n_len == s_len:
                return 1 if n_str == s else 0

            # For numbers with more digits than s, we need to count valid numbers
            # We'll use digit DP approach

            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dp(i, mx, tight):
                # i: current position
                # mx: the maximum allowed digits (string)
                # tight: whether we're still bounded by n

                # Check if we've processed all digits
                if i == len(mx):
                    # Check if the suffix matches s
                    if len(mx) - i == len(s):
                        # Check if the last len(s) digits match s
                        if mx[-len(s):] == s:
                            return 1
                        else:
                            return 0
                    else:
                        return 1

                # If we're at the position where we need to place the suffix
                if len(mx) - i == len(s):
                    # We need to place the suffix s
                    if tight:
                        # We're bounded by n, so we need to check if s fits
                        if mx[i:] == s:
                            return 1
                        else:
                            return 0
                    else:
                        # We're not bounded, so we can place s
                        return 1

                # Otherwise, we can place digits from 0 to min(limit, mx[i] if tight)
                result = 0
                max_digit = limit
                if tight:
                    max_digit = min(max_digit, int(mx[i]))

                for digit in range(0, max_digit + 1):
                    new_tight = tight and (digit == int(mx[i]))
                    new_mx = mx[:i] + str(digit) + mx[i+1:]
                    result += dp(i + 1, new_mx, new_tight)

                return result

            return dp(0, str(n), True)

        return count(finish) - count(start - 1)

