    def numberOfBeautifulIntegers(self, low: int, high: int, k: int) -> int:
        def count_beautiful(num):
            num_str = str(num)
            n = len(num_str)
            memo = {}

            def dp(pos, tight, has_first, even_num, odd_num, remainder):
                if pos == n:
                    return 1 if even_num == odd_num and remainder == 0 else 0

                state = (pos, tight, has_first, even_num, odd_num, remainder)
                if state in memo:
                    return memo[state]

                limit = int(num_str[pos]) if tight else 9
                result = 0

                for digit in range(0, limit + 1):
                    new_tight = tight and (digit == limit)
                    new_has_first = has_first or (digit > 0)

                    if not new_has_first and digit == 0:
                        result += dp(pos + 1, new_tight, False, even_num, odd_num, remainder)
                        continue

                    new_even_num = even_num + (1 if digit % 2 == 0 else 0)
                    new_odd_num = odd_num + (1 if digit % 2 == 1 else 0)
                    new_remainder = (remainder * 10 + digit) % k

                    result += dp(pos + 1, new_tight, new_has_first, new_even_num, new_odd_num, new_remainder)

                memo[state] = result
                return result

            return dp(0, True, False, 0, 0, 0)

        return count_beautiful(high) - count_beautiful(low - 1)
